/* ========================================================================
   顶部 orient bar (含主题切换器)
   ======================================================================== */
.orient-bar{
  position:sticky;top:0;z-index:200;
  display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;
  padding:10px 24px;background:var(--orient-bg);
  border-bottom:1px solid var(--orient-border);backdrop-filter:blur(10px);
  box-shadow:0 2px 12px rgba(0,0,0,0.05);
}
.orient-bar .left{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.orient-bar .left strong{font-family:'Noto Serif SC',serif;font-size:15px;color:var(--orient-text)}
.orient-bar .pill{
  font-size:11px;padding:3px 10px;background:var(--orient-pill-bg);
  border:1px solid var(--orient-pill-border);border-radius:20px;color:var(--orient-pill-text);
}
.orient-bar .right{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.orient-bar button{
  padding:5px 12px;background:var(--orient-btn-bg);border:1px solid var(--orient-btn-border);
  border-radius:6px;font-size:11px;cursor:pointer;font-family:inherit;
  color:var(--orient-btn-text);transition:all 0.15s;
}
.orient-bar button:hover{background:var(--orient-btn-active-bg);border-color:var(--orient-btn-active-bg);color:var(--orient-btn-active-text)}
.orient-bar button.active{background:var(--orient-btn-active-bg);color:var(--orient-btn-active-text);border-color:var(--orient-btn-active-bg)}
.orient-bar button.ghost{background:transparent;border-color:transparent;color:var(--orient-pill-text)}
.orient-bar .theme-current{
  padding:5px 12px;background:#1a1a1a;color:#fff;
  border-radius:6px;font-size:11px;font-family:'JetBrains Mono',monospace;
  letter-spacing:0.05em;
}
.viewport-switcher{display:flex;gap:2px;background:rgba(90,107,58,0.08);padding:2px;border-radius:6px}
.viewport-switcher button{padding:4px 10px;font-size:10px}

/* 主题切换器 */
.theme-switcher{display:flex;gap:4px;align-items:center;flex-wrap:wrap;background:rgba(0,0,0,0.04);padding:4px 6px;border-radius:8px}
.theme-switcher .theme-label{font-size:10px;color:#7d7566;letter-spacing:0.05em;padding:0 4px}
.theme-switcher .theme-btn{
  padding:4px 8px;font-size:10px;background:#fff;border:1px solid #e0d6c0;
  border-radius:4px;cursor:pointer;font-family:inherit;color:#3d3528;
}
.theme-switcher .theme-btn:hover{background:#f0e8d0;border-color:#c9a35c}
.theme-switcher .theme-btn.active{background:#5a6b3a;color:#fff;border-color:#5a6b3a}
.theme-switcher .theme-btn.random{
  background:#1a1a1a;color:#fff;border-color:#1a1a1a;font-weight:600;
}
.theme-switcher .theme-btn.random:hover{background:#333}
.theme-switcher select{
  padding:3px 6px;font-size:10px;background:#fff;border:1px solid #e0d6c0;
  border-radius:4px;font-family:inherit;color:#3d3528;cursor:pointer;
}

.v25-banner{
  text-align:center;padding:10px 24px;background:var(--banner-bg);
  font-size:11px;color:var(--banner-text);border-bottom:1px solid var(--orient-border);
}
.v25-banner .feat{color:#5a6b3a;font-weight:700;padding:0 3px}

/* ========================================================================
   Section 标题 + phone grid
   ======================================================================== */
main{position:relative;z-index:1;padding:20px 0 80px}
.product-section{padding:30px 24px 20px}
.section-head{
  max-width:1400px;margin:0 auto 24px;padding:0 0 12px;
  border-bottom:2px solid var(--section-border);display:flex;align-items:baseline;gap:16px;
}
.section-head h2{
  font-family:'Noto Serif SC',serif;font-size:24px;font-weight:600;
  color:var(--section-text);letter-spacing:0.05em;
}
.section-head p{font-size:12px;color:var(--section-sub);letter-spacing:0.08em}
.section-head .sec-illus{width:30px;height:30px;mix-blend-mode:multiply;opacity:0.85}

.phone-grid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
  gap:28px 20px;max-width:1400px;margin:0 auto;
}

/* ========================================================================
   Phone 外壳
   ======================================================================== */
.phone{
  position:relative;width:100%;max-width:280px;margin:0 auto;
  padding:14px 10px 10px;
  background:var(--phone-bg);
  border-radius:32px;
  box-shadow:
    0 0 0 2px var(--phone-inner-border),
    0 0 0 4px var(--phone-inner-border-2),
    0 12px 24px rgba(0,0,0,0.25),
    inset 0 1px 0 rgba(255,255,255,0.06);
  transition:transform 0.25s,box-shadow 0.25s;
}
.phone:hover{
  transform:translateY(-4px) rotate(-0.4deg);
  box-shadow:
    0 0 0 2px var(--phone-inner-border),
    0 0 0 4px var(--phone-inner-border-2),
    0 20px 36px rgba(0,0,0,0.3),
    inset 0 1px 0 rgba(255,255,255,0.08);
}
.phone::before{
  content:'';position:absolute;top:6px;left:50%;transform:translateX(-50%);
  width:60px;height:4px;background:#1a1a1a;border-radius:4px;z-index:20;
}
.phone-screen{
  position:relative;
  width:100%;aspect-ratio:9/19.5;height:560px;
  border-radius:22px;overflow:hidden;
  background-color:var(--bg, #ffffff);  /* 默认随主题色 */
  background-size:cover;background-position:center;background-repeat:no-repeat;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,0.1);
}
/* portrait 主题: phone-screen 用 --img-bg (用户主动选择的 14 张图) */
body[data-theme^="portrait-"] .phone-screen{
  background-image:var(--img-bg, none);
  background-color:transparent;
}
/* 纯色/渐变/墨水主题: phone-screen 跟随主题色 (--bg) */
body[data-theme^="solid-"] .phone-screen,
body[data-theme^="grad-"] .phone-screen,
body[data-theme="eink"] .phone-screen{
  background:var(--bg, #ffffff);
  background-image:none;
}
.screen-label{
  position:absolute;top:8px;left:8px;z-index:50;
  background:rgba(45,40,30,0.75);color:#faf6ed;font-size:9px;
  padding:2px 6px;border-radius:3px;font-family:'JetBrains Mono',monospace;
  letter-spacing:0.05em;backdrop-filter:blur(2px);
}
.material-chip{
  position:absolute;top:8px;right:8px;z-index:50;
  background:rgba(90,107,58,0.85);color:#fff;font-size:8px;
  padding:2px 5px;border-radius:3px;letter-spacing:0.05em;
}
.screen-scroll{
  position:relative;height:calc(100% - 46px);overflow-y:auto;overflow-x:hidden;
  padding:24px 8px 8px;
}
.screen-scroll::-webkit-scrollbar{width:3px}
.screen-scroll::-webkit-scrollbar-thumb{background:rgba(0,0,0,0.15);border-radius:2px}

/* ========================================================================
   主题水印
   ======================================================================== */
.theme-watermark{
  --wm:var(--img-t1);
  position:absolute;left:6px;bottom:54px;z-index:5;
  width:50px;height:50px;
  background-image:var(--wm);background-size:contain;background-repeat:no-repeat;
  background-position:center;
  mix-blend-mode:multiply;opacity:0.32;
  filter:grayscale(0.2) sepia(0.1);
  pointer-events:none;
}
.theme-watermark[data-project="wd1"]{opacity:0.35;filter:grayscale(0.1) sepia(0.15) hue-rotate(-10deg)}
.theme-watermark[data-project="wd2"]{display:none}
.theme-watermark[data-project="cd"]{opacity:0.32;filter:grayscale(0.2) sepia(0.05) hue-rotate(20deg)}
.theme-watermark[data-project="td"]{opacity:0.32;filter:grayscale(0.15) sepia(0.08) hue-rotate(40deg)}

/* ========================================================================
   角落装饰插画
   ======================================================================== */
.phone-corner{position:absolute;z-index:3;pointer-events:none;mix-blend-mode:multiply;opacity:0.7}
.phone-corner-br{right:4px;bottom:54px;width:70px;height:70px;opacity:0.55}
.phone-corner-bl{left:4px;bottom:54px;width:60px;height:60px;opacity:0.5}
.phone-corner-tr{right:4px;top:46px;width:46px;height:46px;opacity:0.45}
.phone-corner-tl{left:4px;top:46px;width:46px;height:46px;opacity:0.45}

/* wd2 墨水屏：移除所有角落装饰 */
.wd2 .phone-corner{ display: none; }

/* ========================================================================
   印章 / 丝带
   ======================================================================== */
.screen-seal{
  position:absolute;top:30px;right:36px;z-index:10;
  width:38px;height:38px;border-radius:50%;
  border:2px solid;border-color:currentColor;
  display:flex;align-items:center;justify-content:center;
  font-family:'Noto Serif SC',serif;font-size:11px;font-weight:700;
  color:#5a6b3a;background:rgba(250,246,237,0.6);
  transform:rotate(8deg);letter-spacing:0.05em;
  box-shadow:0 2px 8px rgba(0,0,0,0.06);
}
.screen-seal-tl{left:36px;right:auto;top:30px}
.screen-ribbon{
  position:absolute;top:62px;right:6px;z-index:10;
  background:#5a6b3a;color:#fff;padding:3px 10px;
  font-size:9px;font-weight:600;letter-spacing:0.05em;
  border-radius:3px 0 0 3px;box-shadow:-2px 2px 4px rgba(0,0,0,0.1);
}
.screen-ribbon-tl-side{left:6px;right:auto;border-radius:0 3px 3px 0;box-shadow:2px 2px 4px rgba(0,0,0,0.1)}

/* wd2: 移除印章/丝带 */
.wd2 .screen-seal, .wd2 .screen-ribbon { display: none; }

/* ========================================================================
   漂浮小卡
   ======================================================================== */
.float-card{
  position:absolute;z-index:8;
  background:linear-gradient(135deg,rgba(253,249,240,0.95),rgba(245,239,225,0.9));
  border:1px solid #e8e0d0;border-radius:10px;
  padding:5px 8px;box-shadow:0 3px 10px rgba(0,0,0,0.08);
  backdrop-filter:blur(6px);
  display:flex;align-items:center;gap:5px;
  font-size:9px;color:#3d3528;
}
.float-card b{font-family:'Cormorant Garamond',serif;font-size:11px;color:#1a1a1a}
.float-br{right:6px;bottom:120px}
.float-bl{left:6px;bottom:120px}
.float-tr{right:6px;top:46px}
.float-tl{left:6px;top:46px}
.float-mid{left:50%;top:50%;transform:translate(-50%,-50%)}

/* wd2: 移除漂浮卡 */
.wd2 .float-card { display: none; }

/* ========================================================================
   Stat card / row
   ======================================================================== */
.stat-card{
  --accent:#5a6b3a;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:6px 4px;background:linear-gradient(135deg,rgba(250,246,237,0.85),rgba(245,239,225,0.7));
  border:1px solid #e8e0d0;border-radius:10px;
  position:relative;overflow:hidden;
  box-shadow:0 1px 4px rgba(0,0,0,0.04);
}
.stat-card::before{content:'';position:absolute;left:0;top:0;width:3px;height:100%;background:var(--accent);opacity:0.6}
.stat-card .stat-icon{width:16px;height:16px;mix-blend-mode:multiply;opacity:0.85}
.stat-card .stat-num{font-family:'Cormorant Garamond',serif;font-size:16px;font-weight:600;color:var(--accent);margin-top:1px;line-height:1}
.stat-card .stat-lbl{font-size:8px;color:#7d7566;letter-spacing:0.05em;margin-top:2px}

.stat-row{display:flex;gap:5px;margin-bottom:8px}
.stat-row.cols-3 .stat-card{flex:1}
.stat-row.cols-4 .stat-card{flex:1}

/* ========================================================================
   Icon grid (8 个图标小网格)
   ======================================================================== */
.icon-grid{display:grid;gap:5px;margin-bottom:8px}
.icon-grid.cols-4{grid-template-columns:repeat(4,1fr)}
.icon-grid.cols-3{grid-template-columns:repeat(3,1fr)}
.icon-grid-item{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:6px 2px;background:linear-gradient(135deg,rgba(250,246,237,0.7),rgba(245,239,225,0.5));
  border:1px solid #e8e0d0;border-radius:8px;
  font-size:8px;color:#5c5648;cursor:pointer;transition:all 0.15s;
  min-height:44px;gap:3px;
}
.icon-grid-item:hover{background:linear-gradient(135deg,#f0e8d0,#e8e0d0);transform:translateY(-1px)}
.icon-grid-item [class^="img-i"]{width:18px;height:18px;mix-blend-mode:multiply}
.icon-grid-item.dark{background:rgba(45,40,30,0.05);color:#1a1a1a}
.icon-grid-item.dark [class^="img-i"]{filter:invert(0.6)}
.dark-grid{background:rgba(45,40,30,0.04)}

/* ========================================================================
   Tag chip / tag cloud
   ======================================================================== */
.tag-chip{
  display:inline-flex;align-items:center;gap:3px;
  padding:3px 8px;border-radius:20px;font-size:9px;font-weight:500;
  border:1px solid currentColor;line-height:1;
}
.tag-chip .chip-icon{width:10px;height:10px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.tag-cloud{display:flex;flex-wrap:wrap;gap:4px;align-items:center;margin-bottom:8px;padding:6px 4px;background:rgba(250,246,237,0.5);border-radius:8px}
.tag-cloud .mini-label{font-size:8px;color:#7d7566;letter-spacing:0.05em;margin-left:auto;align-self:center}

/* ========================================================================
   Hero banner
   ======================================================================== */
.hero-banner{
  position:relative;border-radius:10px;overflow:hidden;
  height:64px;margin-bottom:8px;
  background:linear-gradient(135deg,rgba(250,246,237,0.6),rgba(245,239,225,0.5));
  border:1px solid #e8e0d0;
}
.hero-banner .hb-bg{
  position:absolute;inset:0;width:100%;height:100%;
  background:linear-gradient(135deg, rgba(245,239,225,0.3) 0%, rgba(250,246,237,0.5) 100%);
  mix-blend-mode:multiply;opacity:0.7;
  z-index:0;
}
.hero-banner .hb-text{position:relative;z-index:1;height:100%;display:flex;flex-direction:column;justify-content:center}
.hero-banner .title{
  padding:6px 10px 0;font-family:'Noto Serif SC',serif;
  font-size:14px;font-weight:600;color:#2e2b24;
}
.hero-banner .title.dark{color:#1a1a1a}
.hero-banner .sub{
  padding:0 10px 6px;font-size:9px;color:#7d7566;
  display:flex;align-items:center;gap:4px;
}
.hero-banner .sub.dark{color:#3d3528}
.hero-banner .sub .sub-icon{width:10px;height:10px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.hero-banner .sub .sub-icon.invert{filter:invert(0.7)}
.hero-banner.hb-short{height:54px}
.hero-banner.hb-tall{height:80px}
.hero-banner.dark-bg{background:linear-gradient(135deg,rgba(245,239,225,0.6),rgba(220,220,220,0.5))}

/* ========================================================================
   cd-banner
   ======================================================================== */
.cd-banner{
  position:relative;width:100%;height:60px;border-radius:10px;
  margin-bottom:8px;overflow:hidden;
  background-size:cover;background-position:center;
  border:1px solid #d0d0d8;
}
.cd-banner .cd-banner-bg{
  position:absolute;inset:0;width:100%;height:100%;
  background:linear-gradient(135deg, rgba(240,244,248,0.3) 0%, rgba(220,230,240,0.4) 100%);
  mix-blend-mode:multiply;opacity:0.6;
}
.cd-banner.cd-banner-short{height:48px}
.cd-banner-text{
  position:absolute;left:8px;bottom:6px;color:#fff;
  font-size:11px;font-weight:600;
  text-shadow:0 1px 3px rgba(0,0,0,0.5);
  font-family:'Noto Serif SC',serif;z-index:2;
}

/* ========================================================================
   Header
   ======================================================================== */
.wd1-header{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #e0d6c0;margin-bottom:8px}
.wd1-header.dark-header{border-bottom-color:#c8c8c8;color:#1a1a1a}
.wd1-brand{
  font-family:'Noto Serif SC',serif;font-size:13px;font-weight:600;
  display:flex;align-items:center;gap:5px;color:#2e2b24;
}
.wd1-brand .brand-icon{width:14px;height:14px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.wd1-brand .brand-icon.invert{filter:invert(0.7)}
.wd1-header-right{display:flex;align-items:center;gap:4px}
.wd1-header .wd1-header-icon{width:16px;height:16px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}

.cd-header{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #d0d0d8;margin-bottom:8px}
.cd-brand{font-family:'JetBrains Mono',monospace;font-size:13px;font-weight:600;display:flex;align-items:center;gap:5px;color:#1a2a3a}
.cd-brand .brand-icon{width:14px;height:14px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.cd-level{font-family:'JetBrains Mono',monospace;font-size:10px;color:#5a6b3a;background:#e8f0d8;padding:2px 6px;border-radius:4px}
.cd-progress{font-family:'JetBrains Mono',monospace;font-size:10px;color:#3a4a5c}
.cd-section-label{font-size:9px;color:#3a4a5c;letter-spacing:0.15em;text-transform:uppercase;margin:6px 0 4px;font-weight:600;display:flex;align-items:center;justify-content:space-between}
.cd-section-label .lbl-icon{width:11px;height:11px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.cd-code{
  background:#1a1a1a;color:#e0e0e0;border-radius:8px;padding:8px 10px;
  font-family:'JetBrains Mono',monospace;font-size:9px;line-height:1.5;margin-bottom:6px;
  white-space:pre-wrap;
}
.cd-code .kw{color:#c9a35c}
.cd-code .str{color:#8fa874}
.cd-hint{font-size:9px;color:#5a6b3a;margin:4px 0 6px;font-family:'JetBrains Mono',monospace;display:flex;align-items:center;gap:4px}
.cd-hint .hint-icon{width:10px;height:10px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.cd-chart{display:flex;align-items:flex-end;gap:4px;height:60px;padding:6px 4px;background:linear-gradient(135deg,#f0f4f8,#e0e8f0);border-radius:8px;margin-bottom:8px}
.cd-chart .bar{flex:1;background:linear-gradient(180deg,#5a6b3a,#3a4a26);border-radius:3px 3px 0 0;transition:all 0.3s}
.cd-chart .bar.active{background:linear-gradient(180deg,#c9a35c,#a6843c)}
.cd-badge-row{display:flex;flex-wrap:wrap;gap:4px;justify-content:center;padding:6px 0;margin-bottom:8px}
.cd-badge{
  width:30px;height:30px;border-radius:6px;background:linear-gradient(135deg,#faf6ed,#f0e8d4);
  border:1px solid #e8e0d0;display:flex;align-items:center;justify-content:center;overflow:hidden;
}
.cd-badge [class^="il-"]{width:24px;height:24px;mix-blend-mode:multiply;opacity:0.85}

/* ========================================================================
   TodoList
   ======================================================================== */
.td-header{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #d8e0e0;margin-bottom:8px}
.td-date{font-family:'Noto Serif SC',serif;font-size:13px;font-weight:600;color:#1a3a3a}
.td-weather{font-size:10px;color:#5a6b3a}
.td-count{font-family:'JetBrains Mono',monospace;font-size:10px;color:#3d5a5a;background:#d8e8e8;padding:2px 6px;border-radius:4px}
.td-header .td-header-icon{width:18px;height:18px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.td-section-label{font-size:9px;color:#3d5a5a;letter-spacing:0.15em;text-transform:uppercase;margin:6px 0 4px;font-weight:600;display:flex;align-items:center;justify-content:space-between}
.td-section-label .lbl-icon{width:11px;height:11px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.td-task{display:flex;align-items:flex-start;gap:8px;padding:7px 0;border-bottom:1px solid #d8e0e0}
.td-task .check{
  width:16px;height:16px;border:1.5px solid #5a6b3a;border-radius:50%;flex-shrink:0;margin-top:1px;
  position:relative;background:transparent;
}
.td-task .check.done{background:#5a6b3a;border-color:#5a6b3a}
.td-task .check.done::after{content:'✓';position:absolute;top:-3px;left:1px;color:#fff;font-size:11px;font-weight:700}
.td-task .content{flex:1;min-width:0}
.td-task .content.done .title,.td-task .content.done .meta{text-decoration:line-through;opacity:0.5}
.td-task .title{font-size:11px;color:#1a3a3a;line-height:1.3}
.td-task .meta{font-size:9px;color:#5a6b3a;margin-top:2px;font-family:'JetBrains Mono',monospace;display:flex;align-items:center;flex-wrap:wrap;gap:1px}
.td-task .meta .meta-icon{width:10px;height:10px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center;margin:0 2px}
.td-dot{display:inline-block;margin:0 3px;color:#c9a35c;font-weight:700}
.td-grid .icon-grid-item{font-size:7.5px}
.td-pomo{display:flex;justify-content:center;padding:14px 0}
.td-pomo-ring{
  width:130px;height:130px;border-radius:50%;
  background:conic-gradient(from 0deg,#a04a3a 0deg,#a04a3a 270deg,#e8e0d0 270deg,#e8e0d0 360deg);
  display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;
}
.td-pomo-ring::before{content:'';position:absolute;inset:8px;border-radius:50%;background:#faf6ed}
.td-pomo-time{font-family:'JetBrains Mono',monospace;font-size:24px;font-weight:600;color:#1a3a3a;z-index:1}
.td-pomo-label{font-size:9px;color:#3d5a5a;z-index:1;margin-top:2px}
.td-pomo-controls{display:flex;gap:6px;margin-bottom:8px;justify-content:center}
.td-pomo-controls button{
  padding:7px 16px;border-radius:8px;font-size:11px;display:flex;
  align-items:center;gap:4px;font-family:inherit;cursor:pointer;
  border:1px solid #3d5a5a;background:#faf6ed;color:#3d5a5a;
}
.td-pomo-controls button .ctrl-icon{width:12px;height:12px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.td-pomo-controls button.pause{background:#a04a3a;color:#fff;border-color:#a04a3a}
.td-pomo-controls button.pause .ctrl-icon.invert{filter:invert(1);mix-blend-mode:normal}
.td-pomo-controls button.reset{background:#faf6ed;color:#3d5a5a}
.td-cal{background:linear-gradient(135deg,#faf6ed,#f0f4f0);border:1px solid #d8e0e0;border-radius:8px;padding:6px;margin-bottom:8px}
.td-cal-header{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;margin-bottom:4px}
.td-cal-header span{text-align:center;font-size:9px;color:#5a6b3a;font-weight:600}
.td-cal-header .weekend{color:#a6443a}
.td-cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}
.td-cal-grid span{text-align:center;font-size:10px;padding:3px 0;color:#1a3a3a;border-radius:4px}
.td-cal-grid .weekend{color:#a6443a}
.td-cal-grid .today{background:#5a6b3a;color:#fff;font-weight:600}
.td-kanban{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin-bottom:6px}
.td-kanban-col{
  background:rgba(250,246,237,0.4);border:1px solid #e8e0d0;
  border-radius:8px;padding:5px 4px;min-height:120px;
}
.td-kanban-title{
  font-size:9px;font-weight:600;color:#3d5a5a;margin-bottom:4px;
  display:flex;align-items:center;gap:3px;letter-spacing:0.05em;
}
.td-kanban-title .kb-icon{width:11px;height:11px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.td-kanban-card{
  background:#faf6ed;border:1px solid #e8e0d0;border-radius:5px;
  padding:3px 4px;margin-bottom:3px;font-size:9px;color:#2e2b24;line-height:1.3;
}

/* ========================================================================
   feat-list / row / r-icon
   ======================================================================== */
.feat-list{border-top:1px solid #e8e0d0;border-bottom:1px solid #e8e0d0;margin-bottom:8px}
.feat-list .row{
  display:flex;align-items:center;gap:6px;padding:5px 4px;
  border-bottom:1px solid rgba(232,224,208,0.5);
  font-size:10px;color:#2e2b24;
}
