.wd1-search{position:relative;display:flex;align-items:center;padding:7px 10px;background:rgba(250,246,237,0.85);border:1px solid #e8e0d0;border-radius:8px;margin-bottom:8px;font-size:11px;color:#7d7566}
.wd1-search .search-icon{width:14px;height:14px;mix-blend-mode:multiply;margin-right:6px;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.wd1-search .search-extra{position:absolute;right:10px;top:50%;transform:translateY(-50%);width:14px;height:14px;mix-blend-mode:multiply;display:inline-block;background-size:contain;background-repeat:no-repeat;background-position:center}
.wd1-alphabet{display:flex;flex-wrap:wrap;gap:3px;padding:4px 0;margin-bottom:8px}
