.ladder-step.active{background:#c9a35c;color:#fff;border-color:#c9a35c;box-shadow:0 0 0 3px rgba(201,163,92,0.18)}

.ring-wrap{display:flex;flex-direction:column;align-items:center;gap:3px}
.ring{
  --p:50;--c:#5a6b3a;
  width:48px;height:48px;border-radius:50%;
  background:conic-gradient(var(--c) calc(var(--p) * 1%),#e8e0d0 0);
  display:flex;align-items:center;justify-content:center;position:relative;
}
.ring::before{content:'';position:absolute;inset:4px;border-radius:50%;background:#faf6ed}
