   ======================================================================== */
.phone-screen.wd2{
  background-color: #ffffff;
  position: relative;
}
/* wd2 屏幕 paper/portrait 背景透出 + 半透 overlay 保证文字可读 */
.phone-screen.wd2::before{
  content:"";
  position: absolute;
  inset: 0;
  background: rgba(248,245,235,0.78);
  pointer-events: none;
  z-index: 0;
}
/* wd2 纯色/渐变/墨水主题时: overlay 更重 (保证黑白) */
body[data-theme="eink"] .phone-screen.wd2::before,
body[data-theme^="solid-"] .phone-screen.wd2::before,
body[data-theme^="grad-"] .phone-screen.wd2::before{
  background: rgba(255,255,255,0.92);
}
.phone-screen.wd2 .screen-scroll{
  position: relative;
  z-index: 2;
}
.phone-screen.wd2 .wd2-tabbar{
  position: relative;
  z-index: 3;
}


